import os
import boto3

def detect_image_labels(image_bytes: bytes) -> dict:
    """
    Detects labels (objects and scenes) in a static image using AWS Rekognition.

    Args:
        image_bytes: The image content in bytes.

    Returns:
        A dictionary containing the detected labels and their confidence scores.
    """
    rekognition_client = boto3.client(
        'rekognition',
        aws_access_key_id=os.environ.get("AWS_ACCESS_KEY_ID"),
        aws_secret_access_key=os.environ.get("AWS_SECRET_ACCESS_KEY"),
        region_name=os.environ.get("AWS_REGION", "us-east-1")
    )

    response = rekognition_client.detect_labels(
        Image={'Bytes': image_bytes}
    )

    labels = []
    for label in response.get('Labels', []):
        labels.append({
            'name': label.get('Name'),
            'confidence': label.get('Confidence')
        })
    return {'labels': labels}

import os
from openai import OpenAI

def summarize_visual_analysis(analysis_results: dict) -> str:
    """
    Summarizes visual analysis results using OpenAI GPT models.

    Args:
        analysis_results: A dictionary containing various analysis outputs (labels, descriptions, text, safety scores).

    Returns:
        A string summarizing the analysis results.
    """
    client = OpenAI(
        api_key=os.environ.get("OPENAI_API_KEY"),
    )

    prompt = f"""
    Summarize the following visual analysis results:
    Labels: {analysis_results.get('labels')}
    Description: {analysis_results.get('description')}
    Detected Text: {analysis_results.get('detected_text')}
    Safety Scores: {analysis_results.get('safety_scores')}
    """

    response = client.chat.completions.create(
        model="gpt-3.5-turbo",  # Using a concrete model identifier
        messages=[{"role": "user", "content": prompt}]
    )

    return response.choices[0].message.content.strip()

import os
from openai import OpenAI

def check_visual_labels_safety(labels_text: str) -> dict:
    """
    Checks generated visual labels for unsafe text content using OpenAI Moderation API.

    Args:
        labels_text: A string containing the combined text of visual labels.

    Returns:
        A dictionary indicating if the text is flagged and detailed moderation categories.
    """
    client = OpenAI(
        api_key=os.environ.get("OPENAI_API_KEY"),
    )

    response = client.moderations.create(
        input=labels_text
    )

    moderation_result = response.results[0]

    return {
        'flagged': moderation_result.flagged,
        'categories': {
            category.replace("_", ""): value
            for category, value in moderation_result.categories.model_dump().items()
        },
        'category_scores': {
            category.replace("_", ""): value
            for category, value in moderation_result.category_scores.model_dump().items()
        }
    }
